package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"strings"

	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
	pb "github.com/example/service/proto"
)

type server struct {
	pb.UnimplementedDataServiceServer
}

// StreamData handles bidirectional streaming - upgrades to WebSocket-like persistent connection
func (s *server) StreamData(stream pb.DataService_StreamDataServer) error {
	md, ok := metadata.FromIncomingContext(stream.Context())
	if !ok {
		return fmt.Errorf("missing metadata")
	}

	// Extract origin from metadata for "validation"
	origins := md.Get("origin")
	authorization := md.Get("authorization")

	// BUG: Origin validation only checks prefix, not full match
	// An attacker can use "https://trusted-app.company.com.evil.com"
	validOrigin := false
	for _, o := range origins {
		if strings.HasPrefix(o, "https://trusted-app.company.com") {
			validOrigin = true
		}
	}

	if !validOrigin && len(origins) > 0 {
		return fmt.Errorf("invalid origin: %v", origins)
	}

	// If no origin header at all, allow (for service-to-service)
	// This is the second bug: missing origin = trusted
	if len(origins) == 0 {
		validOrigin = true
	}

	_ = authorization // Token validation happens "elsewhere" (it doesn't)

	for {
		req, err := stream.Recv()
		if err != nil {
			return err
		}

		// Process commands from the stream - includes sensitive operations
		result := processCommand(req.GetCommand(), req.GetPayload())
		if err := stream.Send(&pb.DataResponse{Result: result}); err != nil {
			return err
		}
	}
}

func processCommand(cmd string, payload []byte) string {
	switch cmd {
	case "read_secret":
		// Reads from mounted service account token or secrets
		data, err := os.ReadFile("/var/run/secrets/kubernetes.io/serviceaccount/token")
		if err != nil {
			return "error: " + err.Error()
		}
		return string(data)
	case "read_config":
		// Reads sensitive config from hostPath mount
		data, err := os.ReadFile("/host/etc/kubernetes/admin.conf")
		if err != nil {
			return "error: " + err.Error()
		}
		return string(data)
	case "exec":
		// Attempts privileged operation
		return execInNamespace(string(payload))
	default:
		return "unknown command"
	}
}

func execInNamespace(ns string) string {
	// Tries to read from /proc/1/ns - requires privileged
	data, err := os.ReadFile(fmt.Sprintf("/proc/1/root/etc/shadow"))
	if err != nil {
		return "error: " + err.Error()
	}
	return string(data)
}

func main() {
	lis, err := net.Listen("tcp", ":50051")
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	// No TLS, no auth interceptor
	s := grpc.NewServer()
	pb.RegisterDataServiceServer(s, &server{})

	// Also expose HTTP health endpoint on same port range
	go func() {
		http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
			w.WriteHeader(200)
		})
		http.ListenAndServe(":8080", nil)
	}()

	log.Printf("gRPC server listening on :50051")
	if err := s.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}
